window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e97ce346033a6325"]={"versions": [{"id": "FIG-e97ce346033a6325", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P07mProtect</code> im AUTOSAR E2E-Protokoll (Profile 7m). Das Diagramm modelliert den internen Funktionsablauf der End-to-End-Absicherung von Multiplex- bzw. flexiblen Kommunikationsdaten vor dem Senden innerhalb der AUTOSAR-Laufzeitumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Funktionsschnittstelle:</p>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P07mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code>\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsparameter des E2E-Profils 7m\n</li><li><code>State</code>: Zustandsspeicher für den Schutzablauf (beinhaltet u. a. den Sequenzzähler)\n</li><li><code>SourceID</code>: Quellidentifikator der Nachricht\n</li><li><code>MessageType</code>: Typ der Nachricht\n</li><li><code>MessageResult</code>: Ergebnisstatus der Nachricht\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload)\n</li><li><code>Length</code>: Länge des Daten-Arrays in Bytes\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Aktionen (Activities mit Call-Behavior-Symbol):</p>\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Write DataID</code>\n</li><li><code>Write SourceID</code>\n</li><li><code>Write Message Type</code>\n</li><li><code>Write Message Result</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n<p class=\"fig-p\">Verzweigungsbedingungen (Guards):</p>\n<ul class=\"fig-list\"><li><code>[null input]</code>\n</li><li><code>[wrong input]</code>\n</li><li><code>[input ok]</code>\n</li></ul>\n<p class=\"fig-p\">Ablaufendpunkte:</p>\n<ul class=\"fig-list\"><li>Drei Aktivitätsendknoten (<code>return</code>) für die Fehler- bzw. Erfolgsfälle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P07mProtect</code>:</p>\n<ol class=\"fig-list\"><li><code>Verify inputs of the protect function</code>: Validierung aller Eingabeparameter.\n<ul class=\"fig-list\"><li>Trifft <code>[null input]</code> zu, verzweigt der Pfad nach links direkt zum Aktivitätsendknoten (<code>return</code>).\n</li><li>Trifft <code>[wrong input]</code> zu, verzweigt der Pfad nach rechts direkt zum Aktivitätsendknoten (<code>return</code>).\n</li><li>Trifft <code>[input ok]</code> zu, wird der sequentielle Hauptpfad durchlaufen:\n</li></ul>\n</li><li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Profil-spezifischen E2E-Felder in <code>Data</code>.\n</li><li><code>Write Length</code>: Schreiben des Längenfelds in den Datenpuffer.\n</li><li><code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in den Datenpuffer.\n</li><li><code>Write DataID</code>: Eintragen des eindeutigen Datenbezeichners.\n</li><li><code>Write SourceID</code>: Eintragen des Quellidentifikators.\n</li><li><code>Write Message Type</code>: Schreiben des Nachrichtentyps.\n</li><li><code>Write Message Result</code>: Schreiben des Nachrichtenergebnisses.\n</li><li><code>Compute CRC</code>: Berechnung der Prüfsumme über die festgelegten Daten- und Headerbereiche.\n</li><li><code>Write CRC</code>: Schreiben des berechneten CRC-Werts in den Datenpuffer.\n</li><li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers im Zustand <code>State</code> für die nachfolgende Nachricht.\n</li><li>Beendigung über den mittleren Aktivitätsendknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00799]</code> ist das dargestellte Gesamtverhalten von <code>E2E_P07mProtect()</code> normativ bindend.</p>\n<ul class=\"fig-list\"><li>Eingangsparameter müssen vor jeder Pufferoperation strikt auf <code>NULL</code>-Zeiger und Wertebereichsverletzungen geprüft werden.\n</li><li>Bei Parameterfehlern bricht die Funktion ohne Modifikation der Nutzdaten oder Zählerstände ab.\n</li><li>Die Inkrementierung des Zählers erfolgt ausschließlich nach erfolgreicher Pufferbefüllung und CRC-Berechnung.\n</li><li>Implementierer müssen sicherstellen, dass die Reihenfolge der Schreiboperationen im Puffer exakt den Feldoffsets und dem Serialisierungsformat des Profils 7m entspricht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ae3b81e6513642fe", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P07mProtect</code> im AUTOSAR E2E-Protokoll (Profile 7m). Das Diagramm modelliert den internen Funktionsablauf der End-to-End-Absicherung von Multiplex- bzw. flexiblen Kommunikationsdaten vor dem Senden innerhalb der AUTOSAR-Laufzeitumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Funktionsschnittstelle:</p>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P07mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code>\n<ul class=\"fig-list\"><li><code>Config</code>: Konfigurationsparameter des E2E-Profils 7m\n</li><li><code>State</code>: Zustandsspeicher für den Schutzablauf (beinhaltet u. a. den Sequenzzähler)\n</li><li><code>SourceID</code>: Quellidentifikator der Nachricht\n</li><li><code>MessageType</code>: Typ der Nachricht\n</li><li><code>MessageResult</code>: Ergebnisstatus der Nachricht\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload)\n</li><li><code>Length</code>: Länge des Daten-Arrays in Bytes\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Aktionen (Activities mit Call-Behavior-Symbol):</p>\n<ul class=\"fig-list\"><li><code>Verify inputs of the protect function</code>\n</li><li><code>Compute offset</code>\n</li><li><code>Write Length</code>\n</li><li><code>Write Counter</code>\n</li><li><code>Write DataID</code>\n</li><li><code>Write SourceID</code>\n</li><li><code>Write Message Type</code>\n</li><li><code>Write Message Result</code>\n</li><li><code>Compute CRC</code>\n</li><li><code>Write CRC</code>\n</li><li><code>Increment Counter</code>\n</li></ul>\n<p class=\"fig-p\">Verzweigungsbedingungen (Guards):</p>\n<ul class=\"fig-list\"><li><code>[null input]</code>\n</li><li><code>[wrong input]</code>\n</li><li><code>[input ok]</code>\n</li></ul>\n<p class=\"fig-p\">Ablaufendpunkte:</p>\n<ul class=\"fig-list\"><li>Drei Aktivitätsendknoten (<code>return</code>) für die Fehler- bzw. Erfolgsfälle.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P07mProtect</code>:</p>\n<ol class=\"fig-list\"><li><code>Verify inputs of the protect function</code>: Validierung aller Eingabeparameter.\n<ul class=\"fig-list\"><li>Trifft <code>[null input]</code> zu, verzweigt der Pfad nach links direkt zum Aktivitätsendknoten (<code>return</code>).\n</li><li>Trifft <code>[wrong input]</code> zu, verzweigt der Pfad nach rechts direkt zum Aktivitätsendknoten (<code>return</code>).\n</li><li>Trifft <code>[input ok]</code> zu, wird der sequentielle Hauptpfad durchlaufen:\n</li></ul>\n</li><li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Profil-spezifischen E2E-Felder in <code>Data</code>.\n</li><li><code>Write Length</code>: Schreiben des Längenfelds in den Datenpuffer.\n</li><li><code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in den Datenpuffer.\n</li><li><code>Write DataID</code>: Eintragen des eindeutigen Datenbezeichners.\n</li><li><code>Write SourceID</code>: Eintragen des Quellidentifikators.\n</li><li><code>Write Message Type</code>: Schreiben des Nachrichtentyps.\n</li><li><code>Write Message Result</code>: Schreiben des Nachrichtenergebnisses.\n</li><li><code>Compute CRC</code>: Berechnung der Prüfsumme über die festgelegten Daten- und Headerbereiche.\n</li><li><code>Write CRC</code>: Schreiben des berechneten CRC-Werts in den Datenpuffer.\n</li><li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers im Zustand <code>State</code> für die nachfolgende Nachricht.\n</li><li>Beendigung über den mittleren Aktivitätsendknoten (<code>return</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00799]</code> ist das dargestellte Gesamtverhalten von <code>E2E_P07mProtect()</code> normativ bindend.</p>\n<ul class=\"fig-list\"><li>Eingangsparameter müssen vor jeder Pufferoperation strikt auf <code>NULL</code>-Zeiger und Wertebereichsverletzungen geprüft werden.\n</li><li>Bei Parameterfehlern bricht die Funktion ohne Modifikation der Nutzdaten oder Zählerstände ab.\n</li><li>Die Inkrementierung des Zählers erfolgt ausschließlich nach erfolgreicher Pufferbefüllung und CRC-Berechnung.\n</li><li>Implementierer müssen sicherstellen, dass die Reihenfolge der Schreiboperationen im Puffer exakt den Feldoffsets und dem Serialisierungsformat des Profils 7m entspricht.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e97ce346033a6325", "to": "FIG-ae3b81e6513642fe", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
